    crate::lua_util::run_actor_named_command(lua, &root, "BeginCommand")?;
    crate::lua_util::run_named_command_on_children_recursively(lua, &root, "BeginCommand", None)?;
    crate::lua_util::run_actor_startup_commands_for_table(lua, &root)
}

