fn legacy_render_states(
    lua: &mlua::Lua,
    frame_clock: Option<[f32; 2]>,
    include_wrappers: bool,
) -> Result<Vec<crate::SongLuaOverlayState>, String> {
    fn visit(
        lua: &mlua::Lua,
        actor: &mlua::Table,
        out: &mut Vec<crate::SongLuaOverlayState>,
        frame_clock: Option<[f32; 2]>,
        include_wrappers: bool,
    ) -> Result<(), String> {
        let mut state = crate::lua_util::live_actor_overlay_state(lua, actor)?;
        crate::lua_util::replay_tween_pose(lua, actor, &mut state);
        if let Some(frame_clock) = frame_clock {
            state.effect_time = crate::lua_util::effect_render_time(actor, frame_clock)
                .map_err(|error| error.to_string())?;
            state.spin_baked = crate::lua_util::spin_render_pose(actor)
                .map_err(|error| error.to_string())?
                .is_some();
        }
        out.push(state);
        for child in
            crate::lua_util::actor_direct_children(lua, actor).map_err(|error| error.to_string())?
        {
            visit(lua, &child, out, frame_clock, include_wrappers)?;
        }
        if include_wrappers {
            for wrapper in crate::lua_util::actor_wrappers(lua, actor)
                .map_err(|error| error.to_string())?
                .sequence_values::<mlua::Table>()
            {
                visit(
                    lua,
                    &wrapper.map_err(|error| error.to_string())?,
                    out,
                    frame_clock,
                    true,
                )?;
            }
        }
        Ok(())
    }
    let root = lua
        .globals()
        .get("root")
        .map_err(|error| error.to_string())?;
    let mut out = Vec::new();
    visit(lua, &root, &mut out, frame_clock, include_wrappers)?;
    Ok(out)
}

